#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    string s, t;
    cin >> s >> t;
    int m = t.size();
    // dp[j]: choices equal to exactly the first j characters of t; greater: already strictly greater.
    vector<long long> dp(m + 1, 0);
    dp[0] = 1;
    long long greater = 0;
    for (char c : s) {
        greater = (greater * 2 + dp[m]) % MOD;
        for (int j = m - 1; j >= 0; j--) {
            if (c > t[j]) greater = (greater + dp[j]) % MOD;
            else if (c == t[j]) dp[j + 1] = (dp[j + 1] + dp[j]) % MOD;
        }
    }
    cout << greater << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1000000007L;
        String s = next(), t = next();
        int m = t.length();
        char[] tc = t.toCharArray();
        // dp[j]: choices equal to exactly the first j characters of t; greater: already strictly greater.
        long[] dp = new long[m + 1];
        dp[0] = 1;
        long greater = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            greater = (greater * 2 + dp[m]) % MOD;
            for (int j = m - 1; j >= 0; j--) {
                if (c > tc[j]) greater = (greater + dp[j]) % MOD;
                else if (c == tc[j]) dp[j + 1] = (dp[j + 1] + dp[j]) % MOD;
            }
        }
        System.out.println(greater);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	const mod = 1000000007
	s, t := readToken(), readToken()
	m := len(t)
	// dp[j]: choices equal to exactly the first j characters of t; greater: already strictly greater.
	dp := make([]int, m+1)
	dp[0] = 1
	greater := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		greater = (greater*2 + dp[m]) % mod
		for j := m - 1; j >= 0; j-- {
			if c > t[j] {
				greater = (greater + dp[j]) % mod
			} else if c == t[j] {
				dp[j+1] = (dp[j+1] + dp[j]) % mod
			}
		}
	}
	fmt.Println(greater)
}
